// AnonymousChatKpiResponse defines model for AnonymousChatKpiResponse.
type AnonymousChatKpiResponse struct {
	// AvgLlmResolutionScore Mean of llm_resolution_score across reviewed sessions (1-5).
	AvgLlmResolutionScore *float64 `json:"avg_llm_resolution_score,omitempty"`

	// ClarificationRate clarification_requests_total / interactions_total; null when no interactions.
	ClarificationRate *float64 `json:"clarification_rate"`

	// ClarificationRequestsTotal Interactions where the assistant asked a clarifying question (ask_user) instead of recommending.
	ClarificationRequestsTotal int `json:"clarification_requests_total"`

	// ClickThroughRate clicks / interactions; null when no interactions.
	ClickThroughRate float64 `json:"click_through_rate"`
	ClicksTotal      int     `json:"clicks_total"`

	// DailyVolume Per-day query counts across the filter window.
	DailyVolume      *[]DailyVolume `json:"daily_volume,omitempty"`
	FeedbackNegative int            `json:"feedback_negative"`
	FeedbackPositive int            `json:"feedback_positive"`
	FlaggedTotal     int            `json:"flagged_total"`

	// HallucinationRate Share of reviewed sessions flagged as hallucinating.
	HallucinationRate *float64 `json:"hallucination_rate,omitempty"`

	// InputTokensTotal Prompt tokens summed over the filtered turns. Turns recorded before per-interaction token capture contribute nothing, so this understates spend on historical data.
	InputTokensTotal  int `json:"input_tokens_total"`
	InteractionsTotal int `json:"interactions_total"`

	// LlmIntentDistribution Counts keyed by llm_intent_category.
	LlmIntentDistribution *map[string]int `json:"llm_intent_distribution,omitempty"`

	// OutputTokensTotal Completion tokens summed over the filtered turns.
	OutputTokensTotal int `json:"output_tokens_total"`

	// ReviewCoverage Reviewed sessions / total reviewable sessions. Operations health signal — drops below ~90% if the review budget is too tight or the task is failing.
	ReviewCoverage *float64 `json:"review_coverage,omitempty"`

	// ReviewInputTokensTotal Prompt tokens spent by the LLM judge. Tracked apart from ``input_tokens_total`` because review runs on its own budget.
	ReviewInputTokensTotal int `json:"review_input_tokens_total"`

	// ReviewOutputTokensTotal Completion tokens spent by the LLM judge.
	ReviewOutputTokensTotal int `json:"review_output_tokens_total"`

	// ReviewedTotal Threads carrying a judge verdict. Always present, unlike the review rates below — zero here is the signal that the nightly pass is off or stalled, so consumers can keep showing the row.
	ReviewedTotal int `json:"reviewed_total"`

	// SatisfactionRate positive / (positive + negative); null when no human feedback.
	SatisfactionRate float64 `json:"satisfaction_rate"`
	SessionsTotal    int     `json:"sessions_total"`

	// SeverityByDay Stacked-bar input. Shape: {labels: [iso-date], series: {NONE: [...], LOW: [...], MEDIUM: [...], HIGH: [...], CRITICAL: [...]}}
	SeverityByDay *SeverityByDay `json:"severity_by_day,omitempty"`

	// UniqueUsers Distinct user_slug values in the window — proxy for active anonymous users.
	UniqueUsers int `json:"unique_users"`
}

